script.lang:
       DO $$
    DECLARE
        constraint_name text;
    BEGIN
        SELECT conname INTO constraint_name
        FROM pg_constraint
                 JOIN pg_class ON pg_constraint.conrelid = pg_class.oid
                 JOIN pg_attribute ON pg_attribute.attrelid = pg_class.oid AND pg_attribute.attnum = ANY(pg_constraint.conkey)
        WHERE relname = 'AMP_INDICATOR_LAYER'
          AND attname = 'created_by'
          AND contype = 'f';

        IF constraint_name IS NOT NULL THEN
            EXECUTE format('ALTER TABLE AMP_INDICATOR_LAYER DROP CONSTRAINT %I', constraint_name);
        END IF;

        EXECUTE 'ALTER TABLE AMP_INDICATOR_LAYER ADD CONSTRAINT fk_created_by_user FOREIGN KEY (created_by) REFERENCES "user"(id)';
    END
$$;
